// HasSourceRevision applies the HasEdge predicate on the "source_revision" edge.
func HasSourceRevision() predicate.ExportArtifact {
	return predicate.ExportArtifact(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, SourceRevisionTable, SourceRevisionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSourceRevisionWith applies the HasEdge predicate on the "source_revision" edge with a given conditions (other predicates).
func HasSourceRevisionWith(preds ...predicate.SourceRevision) predicate.ExportArtifact {
	return predicate.ExportArtifact(func(s *sql.Selector) {
		step := newSourceRevisionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

